private static void DFS(char[][] grid, int row, int col) {
	if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] != '@') {
		return;
	}

	grid[row][col] = '*';
	DFS(grid, row + 1, col);
	DFS(grid, row - 1, col);
	DFS(grid, row, col + 1);
	DFS(grid, row, col - 1);
}

