public int search(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left <= right) {
        int mid = (left + right) >>> 1;
        if (nums[mid] == target) return mid;
        if (nums[mid] >= nums[left]) { // nums[left...mid] is sorted
            if (target >= nums[left] && target <= nums[mid]) { // target is in nums[left...mid]
                right = mid - 1;
            } else { // target is not in nums[left...mid], nums[mid...right] is sorted
                left = mid + 1;
            }
        } else { // nums[mid...right] is sorted
            if (target >= nums[mid] && target <= nums[right]) { // target is in nums[mid...right]
                left = mid + 1;
            } else { // target is not in nums[mid...right], nums[left...mid] is sorted
                right = mid - 1;
            }
        }
    }
    return -1;
}
