public static int calculateEnergy(String s) {
  int currChar, lastChar = 0, maxEnergy = 0, energy = 0;
  for (int i = 0; i < s.length(); i++) {
    currChar = s.charAt(i);
    if (currChar != lastChar) {
      maxEnergy = Math.max(maxEnergy, energy);
      energy = 1;
    } else {
      energy++;
    }
    lastChar = currChar;
  }
  return Math.max(maxEnergy, energy);
}
