public static int minPerfectSquareSum(int n) {
    int result = 0;
    int i = 1;
    while (i * i <= n) {
        int count = 0;
        while (n >= i * i) {
            n -= i * i;
            count++;
        }
        result += count;
        i++;
    }
    return result;
}
